// Close the file to avoid descriptor leaks.
fclose(out);
// No outputs.

// Optionally set a base data path prior to initialization.
// Either use default (NULL) or a random path string.
unsigned choose = *FUZZ_PARAM(unsigned int);
if ((choose & 1u) == 0u) {
    espeak_ng_InitializePath(NULL);
} else {
    std::string p = FUZZ_PARAM_STR();
    // Provide a NUL-terminated C string; content may or may not exist, API will handle errors later.
    espeak_ng_InitializePath(p.c_str());
}
// No outputs; this sets global library state only.

// Initialize the eSpeak NG core. If successful, set a global inited flag.
espeak_ng_STATUS st = espeak_ng_Initialize(context);
if (st != ENS_OK) {
    // Mark not initialized on failure
    FUZZ_SET_ATTR_INT_GLOBAL("ng_inited", 0);
    FUZZ_BAIL();
}
FUZZ_SET_ATTR_INT_GLOBAL("ng_inited", 1);
// Output remains the same pointer-to-handle for reuse by later calls.

// Must be called after successful espeak_ng_Initialize.
if (FUZZ_GET_ATTR_INT_GLOBAL("ng_inited") != 1) { FUZZ_BAIL(); }
unsigned r = *FUZZ_PARAM(unsigned int);
int mode = 0;
if (r & 1u) mode |= ENOUTPUT_MODE_SYNCHRONOUS;
if (r & 2u) mode |= ENOUTPUT_MODE_SPEAK_AUDIO;
int buflen_ms = (int)(*FUZZ_PARAM(unsigned int) % 1000u); // keep small (0..999 ms)
// device: NULL or random name
std::string dev = FUZZ_PARAM_STR();
const char *device = (r & 4u) ? NULL : dev.c_str();
espeak_ng_STATUS st = espeak_ng_InitializeOutput((espeak_ng_OUTPUT_MODE)mode, buflen_ms, device);
if (st != ENS_OK) { FUZZ_BAIL(); }
FUZZ_SET_ATTR_INT_GLOBAL("ng_output_inited", 1);
// No outputs.

// Meaningful only after output initialization.
if (FUZZ_GET_ATTR_INT_GLOBAL("ng_output_inited") != 1) { FUZZ_BAIL(); }
int rate = espeak_ng_GetSampleRate();
// Property: sample rate should be positive when output is initialized.
if (rate <= 0) { FUZZ_BAIL(); }
// No outputs.

// Requires initialization.
if (FUZZ_GET_ATTR_INT_GLOBAL("ng_inited") != 1) { FUZZ_BAIL(); }
int param_val = (int)(*FUZZ_PARAM(unsigned int));
int value = (int)(*FUZZ_PARAM(unsigned int) % 600u); // keep in a broad safe range
int relative = (int)(*FUZZ_PARAM(unsigned int) & 1u); // 0 or 1
espeak_ng_STATUS st = espeak_ng_SetParameter((espeak_PARAMETER)param_val, value, relative);
// Accept non-ENS_OK as valid error returns; only bail on clear misuse (none here).

