if (!log) { FUZZ_BAIL(); }
int flags = (int)(*FUZZ_PARAM(unsigned int) & 0x1u); // only documented bit 0 used
espeak_ng_STATUS st = espeak_ng_CompileDictionary(dsrc.c_str(), dname.c_str(), log, flags, context);
// Close the log to avoid leaks regardless of status
fclose(log);
// Return context back to pool for reuse (function does not consume it).

// Compile phoneme data at a positive sample rate. Context provided by runtime.
