std::string src = FUZZ_PARAM_STR();
std::string dst = FUZZ_PARAM_STR();
FILE *log = tmpfile();
if (!log) { FUZZ_BAIL(); }
espeak_ng_STATUS st = espeak_ng_CompileIntonationPath(src.c_str(), dst.c_str(), log, context);
fclose(log);
// Return context; status may indicate path errors, which is acceptable.

