int length = (int)(*FUZZ_PARAM(unsigned int) % (unsigned int)(maxn + 1)); // 0..maxn
espeak_ng_ENCODING enc = (espeak_ng_ENCODING)((int)(*FUZZ_PARAM(unsigned int) % (int)ESPEAKNG_ENCODING_ISO_10646_UCS_2 + 1));
// Call decode; accept any status.
espeak_ng_STATUS st = text_decoder_decode_string(decoder, data.data(), length, enc);
// Mark that we attempted to feed data; downstream can require fed>0 for read ops.
FUZZ_SET_ATTR_INT(decoder, "fed", 1);
// Return decoder for continued use.

