if (FUZZ_GET_ATTR_INT(decoder, "decoder_inited") != 1) { FUZZ_BAIL(); }
std::string data = FUZZ_PARAM_STR();
size_t maxn = std::min<size_t>(data.size(), 256u);
int length = (int)(*FUZZ_PARAM(unsigned int) % (unsigned int)(maxn + 1));
espeak_ng_ENCODING hint = (espeak_ng_ENCODING)((int)(*FUZZ_PARAM(unsigned int) % (int)ESPEAKNG_ENCODING_ISO_10646_UCS_2 + 1));
espeak_ng_STATUS st = text_decoder_decode_string_auto(decoder, data.data(), length, hint);
FUZZ_SET_ATTR_INT(decoder, "fed", 1);
// Return decoder to persist state.

