if (FUZZ_GET_ATTR_INT(decoder, "decoder_inited") != 1) { FUZZ_BAIL(); }
if (FUZZ_GET_ATTR_INT(decoder, "fed") == 0) { FUZZ_BAIL(); }
int eof = text_decoder_eof(decoder);
// No property asserted beyond non-crash; return decoder for reuse.

