if (eof) { FUZZ_BAIL(); }
uint32_t cp = text_decoder_peekc(decoder);
(void)cp;
// Return decoder.

// Obtain a read-only internal buffer pointer. Decoder must be valid.
if (FUZZ_GET_ATTR_INT(decoder, "decoder_inited") != 1) { FUZZ_BAIL(); }
const void *p = text_decoder_get_buffer(decoder);
(void)p; // Do not dereference; lifetime owned by decoder per API.
// Return decoder for continued use.

// Initialize classic eSpeak API and record global state for dependent calls.
int output_modes[] = { 0, 1, 2, 3 }; // fallback values; real enum comes from headers
int mode = output_modes[*FUZZ_PARAM(unsigned int) % 4];
int buflen_ms = (int)(*FUZZ_PARAM(unsigned int) % 600u); // 0..599 ms
unsigned pick = *FUZZ_PARAM(unsigned int);
const char *path = (pick & 1u) ? (const char *)NULL : FUZZ_PARAM_FILENAME();
int options = (int)(*FUZZ_PARAM(unsigned int) & 0x8003u); // use documented bits: 0,1,15
