unsigned int position = (unsigned int)(text.empty() ? 0u : (*FUZZ_PARAM(unsigned int) % (unsigned int)text.size()));
espeak_POSITION_TYPE pos_type = (espeak_POSITION_TYPE)((int)(*FUZZ_PARAM(unsigned int) % 3));
